import type { Metadata } from 'next';
import { notFound } from 'next/navigation';
import Link from 'next/link';
import { ChevronRight, ArrowLeft } from 'lucide-react';
import { getNodeById, getChildNodes, getNodePath } from '@/lib/data';
import { TaskCard } from '@/components/TaskCard';

interface Props {
  params: Promise<{ id: string }>;
}

export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const { id } = await params;
  const node = await getNodeById(decodeURIComponent(id));

  if (!node) {
    return { title: 'Node Not Found' };
  }

  return {
    title: node.name,
    description: `Explore the ${node.node_type.toLowerCase()} "${node.name}" in TASKPEDIA. ${node.description || ''}`,
  };
}

export default async function NodePage({ params }: Props) {
  const { id } = await params;
  const nodeId = decodeURIComponent(id);
  const node = await getNodeById(nodeId);

  if (!node) {
    notFound();
  }

  const children = await getChildNodes(nodeId);
  const path = await getNodePath(nodeId);

  const typeColors: Record<string, string> = {
    DOMAIN: 'bg-blue-100 text-blue-700',
    TASK: 'bg-purple-100 text-purple-700',
    SUBTASK: 'bg-orange-100 text-orange-700',
    ATOMIC: 'bg-green-100 text-green-700',
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 via-blue-50 to-slate-100 py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-5xl mx-auto">
        <Link
          href="/explore"
          className="inline-flex items-center space-x-2 text-gray-600 hover:text-gray-900 mb-6"
        >
          <ArrowLeft className="w-4 h-4" />
          <span>Back to Explore</span>
        </Link>

        <nav className="flex items-center space-x-2 text-sm mb-8 overflow-x-auto pb-2">
          {path.map((p, idx) => (
            <span key={p.id} className="flex items-center space-x-2 whitespace-nowrap">
              {idx > 0 && <ChevronRight className="w-4 h-4 text-gray-400" />}
              <Link
                href={`/node/${encodeURIComponent(p.id)}`}
                className={`hover:text-primary-600 ${
                  idx === path.length - 1 ? 'text-gray-900 font-medium' : 'text-gray-500'
                }`}
              >
                {p.name}
              </Link>
            </span>
          ))}
        </nav>

        <div className="bg-white rounded-2xl shadow-lg p-8 border border-gray-200 mb-8">
          <div className="flex items-start justify-between mb-4">
            <span className={`px-3 py-1 rounded-lg text-sm font-semibold ${typeColors[node.node_type]}`}>
              {node.node_type}
            </span>
          </div>

          <h1 className="text-3xl lg:text-4xl font-bold text-gray-900 mb-4">
            {node.name}
          </h1>

          {node.description && (
            <p className="text-lg text-gray-600 mb-6">{node.description}</p>
          )}

          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 p-4 bg-gray-50 rounded-xl">
            <div>
              <p className="text-xs text-gray-500 uppercase font-medium">ID</p>
              <p className="text-sm font-mono text-gray-900 truncate">{node.id}</p>
            </div>
            <div>
              <p className="text-xs text-gray-500 uppercase font-medium">Type</p>
              <p className="text-sm text-gray-900">{node.node_type}</p>
            </div>
            <div>
              <p className="text-xs text-gray-500 uppercase font-medium">Children</p>
              <p className="text-sm text-gray-900">{children.length}</p>
            </div>
            <div>
              <p className="text-xs text-gray-500 uppercase font-medium">Sources</p>
              <p className="text-sm text-gray-900">{node.sources?.join(', ') || 'N/A'}</p>
            </div>
          </div>
        </div>

        {children.length > 0 && (
          <div>
            <h2 className="text-2xl font-bold text-gray-900 mb-6">
              Child Nodes ({children.length})
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {children.map((child) => (
                <TaskCard key={child.id} task={child} />
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
